import shutil
from datetime import datetime
from pathlib import Path

from langchain_core.tools import tool


@tool
def rotate_log_file(log_path: str, archive_dir: str) -> dict:
    if not log_path or not archive_dir:
        return {"ok": False, "error": "log_path and archive_dir are required"}

    src = Path(log_path)
    if not src.is_file():
        return {"ok": False, "error": f"log file not found: {log_path}"}

    dest_dir = Path(archive_dir)
    if dest_dir.exists() and not dest_dir.is_dir():
        return {"ok": False, "error": "archive_dir is not a directory"}

    dest_dir.mkdir(parents=True, exist_ok=True)
    stamp = datetime.utcnow().strftime("%Y%m%dT%H%M%SZ")
    dest = dest_dir / f"{src.stem}.{stamp}{src.suffix}"
    if dest.exists():
        return {"ok": False, "error": f"archive target already exists: {dest}"}

    shutil.move(str(src), str(dest))
    src.touch()
    return {"ok": True, "archived_to": str(dest), "new_log": str(src)}

import json
from dataclasses import dataclass
from pathlib import Path

from agents import function_tool


@dataclass
class ScanResult:
    new_lines: int
    warnings: int
    errors: int
    start_offset: int
    end_offset: int
    reset: bool


@function_tool
def scan_new_log_entries(log_path: str, checkpoint_path: str) -> ScanResult:
    log = Path(log_path)
    cp = Path(checkpoint_path)
    offset = 0
    if cp.is_file():
        offset = json.loads(cp.read_text()).get(log_path, 0)

    size = log.stat().st_size
    reset = offset > size
    if reset:
        offset = 0

    warnings = errors = lines = 0
    with log.open("rb") as fh:
        fh.seek(offset)
        for raw in fh:
            lines += 1
            text = raw.decode("utf-8", errors="replace")
            if " ERROR " in text or " CRITICAL " in text:
                errors += 1
            elif " WARNING " in text:
                warnings += 1
        end = fh.tell()

    state = json.loads(cp.read_text()) if cp.is_file() else {}
    state[log_path] = end
    cp.write_text(json.dumps(state))
    return ScanResult(lines, warnings, errors, offset, end, reset)
